/bin/bash -lc "node check.js; node --check logic.js; node <<'NODE'
const assert = require('node:assert/strict');
const { retry_delay } = require('./logic');
for (let attempt = 0; attempt <= 60; attempt++) {
  for (const base of [0, 1, 2, 3, 10, Number.MAX_SAFE_INTEGER]) {
    for (const cap of [0, 1, 7, 1000, Number.MAX_SAFE_INTEGER]) {
      const backoff = BigInt(base) * (2n ** BigInt(attempt));
      const expected = Number(backoff < BigInt(cap) ? backoff : BigInt(cap));
      assert.equal(retry_delay(attempt, base, cap), expected);
    }
  }
}
assert.equal(retry_delay(60, Number.MAX_VALUE, Number.MAX_VALUE), Number.MAX_VALUE);
console.log('Existing checks, syntax check, and backoff boundary verification passed.');
NODE"

